	scanner := bufio.NewScanner(os.Stdin)
	firstLine := true

	for scanner.Scan() {
		line := scanner.Text()

		if firstLine {
			firstLine = false
			continue
		}

		ans := 0
		words := strings.Fields(line)

		for _, word := range words {
			curr := 0
			for _, r := range word {
				if r >= 'A' && r <= 'Z' {
					curr++
				}
			}
			if curr > ans {
				ans = curr
			}
		}

		fmt.Println(ans)
	}
}

