func main() {
	scanner := bufio.NewScanner(os.Stdin)
	c := 0

	for scanner.Scan() {
		str := scanner.Text()
		if c == 0 {
			c++
			continue
		}

		ans := 0
		arr := strings.Fields(str)

		for i := 0; i < len(arr); i++ {
			curr := 0
			for j := 0; j < len(arr[i]); j++ {
				ch := arr[i][j]
				if ch >= 'A' && ch <= 'Z' {
					curr++
				}
			}
			if curr > ans {
				ans = curr
			}
		}

		fmt.Println(ans)
		c++
	}
}

