	scanner := bufio.NewScanner(os.Stdin)
	lineCount := 0

	for scanner.Scan() {
		if lineCount == 0 {
			lineCount++
			continue
		}

		line := scanner.Text()
		words := strings.Fields(line)
		maxUpper := 0

		for _, word := range words {
			count := 0
			for _, r := range word {
				if r >= 'A' && r <= 'Z' {
					count++
				}
			}
			if count > maxUpper {
				maxUpper = count
			}
		}

		fmt.Println(maxUpper)
		lineCount++
	}
}

